import sys
from collections import deque

def read_input():
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    k = int(input[2])
    flowers = []
    index = 3
    for _ in range(n):
        row = list(map(int, input[index:index + m]))
        flowers.append(row)
        index += m
    important_squares = []
    for _ in range(k):
        x = int(input[index]) - 1
        y = int(input[index + 1]) - 1
        important_squares.append((x, y))
        index += 2
    return n, m, k, flowers, important_squares

def bfs(plan, start, visited):
    queue = deque([start])
    visited.add(start)
    while queue:
        x, y = queue.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(plan) and 0 <= ny < len(plan[0]) and plan[nx][ny] == 'X' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))

def is_connected(plan, important_squares):
    visited = set()
    bfs(plan, important_squares[0], visited)
    return all(square in visited for square in important_squares)

def solve(n, m, k, flowers, important_squares):
    from itertools import combinations
    min_dead_plants = float('inf')
    best_plan = None
    for combination in combinations([(x, y) for x in range(n) for y in range(m)], k):
        plan = [['.' for _ in range(m)] for _ in range(n)]
        dead_plants = 0
        for x, y in combination:
            plan[x][y] = 'X'
            dead_plants += flowers[x][y]
        for x, y in important_squares:
            if plan[x][y] != 'X':
                plan[x][y] = 'X'
                dead_plants += flowers[x][y]
        if is_connected(plan, important_squares):
            if dead_plants < min_dead_plants:
                min_dead_plants = dead_plants
                best_plan = plan
    return min_dead_plants, best_plan

def main():
    n, m, k, flowers, important_squares = read_input()
    min_dead_plants, best_plan = solve(n, m, k, flowers, important_squares)
    print(min_dead_plants)
    for row in best_plan:
        print(''.join(row))

main()
